func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var s string
	fmt.Fscan(in, &s)
	fmt.Println(solve(s))
}

func solve(s string) int {
	// Try every possible order of removals greedily by always removing
	// the rightmost removable character first.
	best := 0
	str := []byte(s)
	for {
		idx := -1
		for i := len(str) - 1; i >= 0; i-- {
			if removable(str, i) {
				idx = i
				break
			}
		}
		if idx == -1 {
			break
		}
		str = append(str[:idx], str[idx+1:]...)
		best++
	}
	return best
}

func removable(s []byte, i int) bool {
	c := s[i]
	if c == 'a' {
		return false
	}
	prev := c - 1
	if i > 0 && s[i-1] == prev {
		return true
	}
	if i < len(s)-1 && s[i+1] == prev {
		return true
	}
	return false
}
